// spec: specs/nav-menu-a11y.md (2.1) · кейс: .qa/tests/nav-menu-a11y/NAV-A11Y-03.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение: не-GET обрываются, SW выключен. WhatsApp не нажимается.
// Источник: #0651d2 «מה רצוי» — «התחברות» и «פרסום עסק למכירה» видны и нажимаются целиком при открытом меню
// («למשל» — скрыть плавающие кнопки; программист выбрал скрытие, PR #200).
// На /search 375 «פרסום עסק למכירה» ниже края окна (меню прокручивается) — перед hit-test прокручиваем её в видимую часть.
import { test, expect } from '@playwright/test';
import { PageKey, pathOf, prepareReadOnly, dismissPopups, waitReady, LOAD } from '../html-rtl-dir/rtl-dir.helpers';
import { whatsapp, a11yButton, openMenu, expectFloatingHidden, menuAction, hitTest } from './floating.helpers';

test.use({ serviceWorkers: 'block' });

const PAGES: PageKey[] = ['home', 'search'];
const WIDTHS = [
  { width: 375, height: 812 },
  { width: 390, height: 844 },
];
const ACTIONS = ['התחברות', 'פרסום עסק למכירה'];

for (const viewport of WIDTHS) {
  test.describe(`Открытое мобильное меню ${viewport.width}px — плавающие кнопки не перекрывают низ меню`, () => {
    test.use({ viewport });

    for (const key of PAGES) {
      test(`${key} ${viewport.width}: при открытом меню WhatsApp и נגישות скрыты, левый край и центр «התחברות» и «פרסום עסק למכירה» — сама кнопка #0651d2 @mobile @prod-safe`, async ({ page, context, request }) => {
        const path = await pathOf(request, key);
        await prepareReadOnly(context);
        await dismissPopups(page);
        await page.goto(path);
        await waitReady(page, key);
        await expect(whatsapp(page), 'до открытия: плавающий WhatsApp виден').toBeVisible(LOAD);
        await expect(a11yButton(page), 'до открытия: плавающая נגישות видна').toBeVisible(LOAD);

        const menu = await openMenu(page);
        await expectFloatingHidden(page, `${path} ${viewport.width}, меню открыто`);

        for (const text of ACTIONS) {
          const target = menuAction(menu, text);
          await expect(target, `«${text}» в меню`).toBeVisible();
          const hits = await hitTest(target);
          for (const h of hits) {
            expect(h.inViewport, `«${text}» ${h.point} (${h.x},${h.y}) в окне`).toBe(true);
            expect(h.ok, `«${text}» ${h.point} (${h.x},${h.y}): попадание в саму кнопку, а не в ${h.hit}`).toBe(true);
          }
        }
      });
    }
  });
}
